INSERT INTO notas (id, titulo, dominio_slug, aplicacao_slug, tipo_nota_slug, camadas, sinais, confianca, status, corpo) VALUES (
  $m4704$nota-0186$m4704$, $m4705$Cinco princípios da adaptação ao treinamento: sobrecarga, especificidade, progressão, reversibilidade, individualidade$m4705$, $m4706$metodologia-e-periodizacao$m4706$,
  $m4707$contexto$m4707$, $m4708$conceito$m4708$,
  ARRAY[$m4709$semanal$m4709$, $m4710$mensal$m4710$]::text[], '{}'::text[],
  0.55, $m4711$ativo$m4711$, $m4712$Cinco princípios fisiológicos que regem qualquer método de treinamento: (1) Sobrecarga — o estímulo precisa perturbar a homeostase o suficiente para gerar adaptação, mas excesso aumenta risco de overreaching; (2) Especificidade — o organismo se adapta exatamente ao estímulo recebido (treino de potência máxima ≠ treino de endurance); (3) Progressão — estímulos precisam aumentar (volume, intensidade, frequência ou complexidade) à medida que o atleta se adapta; (4) Reversibilidade — adaptações regridem quando o treino é interrompido, em velocidades diferentes por capacidade; (5) Individualidade — a mesma sessão produz respostas diferentes em atletas diferentes.

Aplicação ao feedback: framework de referência geral (SAID/FITT) — não gera regra de interpretação direta de um dado isolado do Strava, mas justifica por que o feedback do produto deveria considerar histórico/progressão do atleta (não comparar sessões isoladas sem contexto) e por que perda de forma após períodos sem treino (detectável via queda de CTL/TSB, já no cânone do Livro 1) é esperada e não anômala.$m4712$
)
